ЧЕ ЗНАЧЕНИЕ(Справочник.ЦМО.ПустаяСсылка) КОНЕЦ КАК ЦМО, ЕПСБУДвиженияССубконто.Организация КАК Организация, ЕПСБУДвиженияССубконто.СчетКт КАК СчетКт, ЕПСБУДвиженияССубконто.СчетДт КАК СчетДт, ЕПСБУДвиженияССубконто.Сумма КАК СуммаНоменклатура, ЕПСБУДвиженияССубконто.КоличествоДт КАК Количество ПОМЕСТИТЬ ВТ_Движения ИЗ РегистрБухгалтерии.ЖурналПроводокЕПСБУ.ДвиженияССубконто( &НачалоПериода, &КонецПериода, Активность = ИСТИНА И СчетДт В (ВЫБРАТЬ Счета10502.СчетЕПСБУ ИЗ Счета10502) И (НЕ &ТолькоОтПоставщиков ИЛИ СчетКт В (ВЫБРАТЬ КорСчет.СчетЕПСБУ ИЗ КорСчет)) И (&УчитыватьВнутренниеОбороты ИЛИ НЕ СчетКт В (ВЫБРАТЬ Счета10502.СчетЕПСБУ ИЗ Счета10502)) И НЕ Регистратор ССЫЛКА Документ.ЗакрытиеГодаТехнологическое, , ) КАК ЕПСБУДвиженияССубконто ГДЕ ВЫРАЗИТЬ(ЕПСБУДвиженияССубконто.СубконтоДт1 КАК Справочник.Номенклатура).ТипНоменклатуры = ЗНАЧЕНИЕ(Перечисление.ТипыНоменклатуры.ПродуктыПитания) {ГДЕ (ВЫБОР КОГДА ЕПСБУДвиженияССубконто.СубконтоКт1 ССЫЛКА Справочник.Контрагенты ТОГДА ЕПСБУДвиженияССубконто.СубконтоКт1 КОГДА ЕПСБУДвиженияССубконто.СубконтоКт2 ССЫЛКА Справочник.Контрагенты ТОГДА ЕПСБУДвиженияССубконто.СубконтоКт2 КОГДА ЕПСБУДвиженияССубконто.СубконтоКт3 ССЫЛКА Справочник.Контрагенты ТОГДА ЕПСБУДвиженияССубконто.СубконтоКт3 КОГДА ЕПСБУДвиженияССубконто.СубконтоКт1 ССЫЛКА Справочник.Договоры ТОГДА ВЫРАЗИТЬ(ЕПСБУДвиженияССубконто.СубконтоКт1 КАК Справочник.Договоры).Контрагент КОГДА ЕПСБУДвиженияССубконто.СубконтоКт2 ССЫЛКА Справочник.Договоры ТОГДА ВЫРАЗИТЬ(ЕПСБУДвиженияССубконто.СубконтоКт2 КАК Справочник.Договоры).Контрагент КОГДА ЕПСБУДвиженияССубконто.СубконтоКт3 ССЫЛКА Справочник.Договоры ТОГДА ВЫРАЗИТЬ(ЕПСБУДвиженияССубконто.СубконтоКт3 КАК Справочник.Договоры).Контрагент КОГДА ЕПСБУДвиженияССубконто.ХарактеристикаДвиженияКт ССЫЛКА Справочник.Контрагенты ТОГДА ЕПСБУДвиженияССубконто.ХарактеристикаДвиженияКт ИНАЧЕ ЗНАЧЕНИЕ(Справочник.Контрагенты.ПустаяСсылка) КОНЕЦ).* КАК Контрагент, ЕПСБУДвиженияССубконто.ИФО.*, ЕПСБУДвиженияССубконто.КФО.*, ЕПСБУДвиженияССубконто.ПодразделениеДт.* КАК Подразделение, ЕПСБУДвиженияССубконто.КПСДт.* КАК КПС, (ВЫБОР КОГДА ТИПЗНАЧЕНИЯ(ЕПСБУДвиженияССубконто.СубконтоДт1) = ТИП(Справочник.Номенклатура) ТОГДА ВЫРАЗИТЬ(ЕПСБУДвиженияССубконто.СубконтоДт1 КАК Справочник.Номенклатура) ИНАЧЕ ЗНАЧЕНИЕ(Справочник.Номенклатура.ПустаяСсылка) КОНЕЦ).* КАК Номенклатура, (ВЫБОР КОГДА ТИПЗНАЧЕНИЯ(ЕПСБУДвиженияССубконто.СубконтоДт2) = ТИП(Справочник.ЦМО) ТОГДА ВЫРАЗИТЬ(ЕПСБУДвиженияССубконто.СубконтоДт2 КАК Справочник.ЦМО) ИНАЧЕ ЗНАЧЕНИЕ(Справочник.ЦМО.ПустаяСсылка) КОНЕЦ).* КАК ЦМО, ЕПСБУДвиженияССубконто.Организация.*, ЕПСБУДвиженияССубконто.СчетКт.*, ЕПСБУДвиженияССубконто.СчетДт.*, (ВЫБОР КОГДА ТИПЗНАЧЕНИЯ(ЕПСБУДвиженияССубконто.СубконтоДт1) = ТИП(Справочник.Номенклатура) ТОГДА ВЫРАЗИТЬ(ЕПСБУДвиженияССубконто.СубконтоДт1 КАК Справочник.Номенклатура) ИНАЧЕ ЗНАЧЕНИЕ(Справочник.Номенклатура.ПустаяСсылка) КОНЕЦ).* КАК Номенклатура} ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_Движения.Период КАК Период, ВТ_Движения.Контрагент КАК Контрагент, ВЫБОР КОГДА ТИПЗНАЧЕНИЯ(ВТ_Движения.Контрагент.ЮридическоеФизическоеЛицо) = ТИП(Справочник.ЮридическиеЛица) ТОГДА ВЫРАЗИТЬ(ВТ_Движения.Контрагент.ЮридическоеФизическоеЛицо.НаименованиеПолное КАК СТРОКА(512)) ИНАЧЕ ВЫРАЗИТЬ(ВТ_Движения.Контрагент КАК Справочник.Контрагенты).Наименование КОНЕЦ КАК КонтрагентНаименование, ВТ_Движения.Контрагент.Код КАК КонтрагентКод, ВТ_Движения.Регистратор КАК Регистратор, СУММА(ВТ_Движения.СуммаКонтрагент) КАК СуммаКонтрагент, ВТ_Движения.СчетКт КАК СчетКт, ВТ_Движения.СчетДт КАК СчетДт, ВТ_Движения.Номенклатура КАК Номенклатура, ВТ_Движения.Номенклатура.Код КАК НоменклатураКод, ВТ_Движения.Номенклатура.ЕдиницаИзмерения КАК ЕдиницаИзмерения, СУММА(ВТ_Движения.СуммаНоменклатура) КАК СуммаНоменклатура, СУММА(ВТ_Движения.Количество) КАК Количество, ВТ_Движения.Организация КАК Организация, ВЫБОР КОГДА ДЛИНАСТРОКИ(ВЫРАЗИТЬ(ВТ_Движения.Регистратор КАК Документ.ПоступлениеМЗ).НомерПервичногоДокумента) = 0 ТОГДА NULL ИНАЧЕ ВЫРАЗИТЬ(ВТ_Движения.Регистратор КАК Документ.ПоступлениеМЗ).НомерПервичногоДокумента КОНЕЦ КАК НомерПервичногоДокумента {ВЫБРАТЬ Период, Контрагент.*, КонтрагентНаименование, КонтрагентКод, Регистратор.*, СуммаКонтрагент, СчетКт.*, СчетДт.*, Номенклатура.*, НоменклатураКод, НомерПервичногоДокумента, ЕдиницаИзмерения.* КАК ЕдиницаИзмерения, СуммаНоменклатура, Количество, Организация.*} ИЗ ВТ_Движения КАК ВТ_Движения {ГДЕ ВТ_Движения.Период}
СГРУППИРОВАТЬ ПО ВТ_Движения.Период, ВТ_Движения.Контрагент, ВТ_Движения.Регистратор, ВТ_Движения.СчетКт, ВТ_Движения.СчетДт, ВТ_Движения.Номенклатура, ВТ_Движения.Организация, ВЫБОР КОГДА ДЛИНАСТРОКИ(ВЫРАЗИТЬ(ВТ_Движения.Регистратор КАК Документ.ПоступлениеМЗ).НомерПервичногоДокумента) = 0 ТОГДА NULL ИНАЧЕ ВЫРАЗИТЬ(ВТ_Движения.Регистратор КАК Документ.ПоступлениеМЗ).НомерПервичногоДокумента КОНЕЦ, ВТ_Движения.Контрагент.Код, ВТ_Движения.Номенклатура.Код, ВТ_Движения.Номенклатура.ЕдиницаИзмерения, ВЫБОР КОГДА ТИПЗНАЧЕНИЯ(ВТ_Движения.Контрагент.ЮридическоеФизическоеЛицо) = ТИП(Справочник.ЮридическиеЛица) ТОГДА ВЫРАЗИТЬ(ВТ_Движения.Контрагент.ЮридическоеФизическоеЛицо.НаименованиеПолное КАК СТРОКА(512)) ИНАЧЕ ВЫРАЗИТЬ(ВТ_Движения.Контрагент КАК Справочник.Контрагенты).Наименование КОНЕЦ
ИМЕЮЩИЕ СУММА(ВТ_Движения.СуммаКонтрагент) <> 0 И (СУММА(ВТ_Движения.СуммаНоменклатура) <> 0 ИЛИ СУММА(ВТ_Движения.Количество) <> 0)
